; COMBAT module: Goku's fighting on the field (port of engine/mana-mod.js and
; the native adapters native-interaction, native-combat-sound,
; native-hit-recovery, native-feedback, native-equipment, native-senzu).
; Spec: docs/agents/combat.md; port notes and API: docs/agents/snes-port/combat.md.
;
; Resources:
;   code  $A2:8000-EFFF (!CODE_COMBAT); $A2:F000-FFFF is reserved for
;         bind.asm (bindings to optional modules, assembled last)
;   data  $E2:0000-7FFF (!DATA_COMBAT), generated by snes/gen/combat.mjs
;   WRAM  $7E:D800-D8FF (!RAM_COMBAT)
;   SRAM  $31:7C00-7FFF (!SRAM_WORK_COMBAT): effects, launches, sound marks,
;         beam pulse timers; !PERSIST_COMBAT ($31:6200): first-reveal latch
;   OAM/VRAM only for the placeholder effects (!COMBAT_FX_PLACEHOLDER)
;
; Every routine here runs with X/Y 16-bit; immediates carry .b/.w for the M
; state at that point (asar does not track REP/SEP).

incsrc "combat/defines.asm"

; ---------------------------------------------------------------------------
; WRAM (!RAM_COMBAT = $7E:D800, $100 bytes): absolute addresses for DB = $7E.
!CB = $D800
assert !RAM_COMBAT == $7E0000|!CB, "!CB must match !RAM_COMBAT"
!cb_init       = !CB+$00   ; byte: $A5 once the SRAM tables were cleared
!cb_sess       = !CB+$01   ; byte: native menu session (mana-mod menuTransition)
!cb_in         = !CB+$02   ; word: combat input (pad layout; Y = ki, X = ring/back)
!cb_in_prev    = !CB+$04   ; word: previous combat input (lastInput)
!cb_pad        = !CB+$06   ; word: pad after the menu-held filter (padInput)
!cb_pad_prev   = !CB+$08   ; word: lastPadInput
!cb_menu_held  = !CB+$0A   ; word: buttons held since a menu (menuInputHeld)
!cb_frame      = !CB+$0C   ; word: combat frame counter (mod.frame)
!cb_map        = !CB+$0E   ; word: map of the last frame ($FFFF none)
!cb_facing     = !CB+$10   ; byte: 0 down, 1 right, 2 left, 3 up
!cb_form       = !CB+$11   ; byte: 1 = Super Saiyan (options.superSaiyan)
!cb_can        = !CB+$12   ; byte: canAttack this frame (read-only for others)
!cb_gc         = !CB+$13   ; byte: Goku is player 1's character
!cb_act        = !CB+$14   ; byte: action kind (!GOKU_K_*), 0 none
!cb_act_face   = !CB+$15   ; byte: action facing
!cb_act_age    = !CB+$16   ; word
!cb_act_dur    = !CB+$18   ; word: duration (0 = open-ended)
!cb_act_arg    = !CB+$1A   ; byte: punch combo / blast hand
!cb_act_super  = !CB+$1B   ; byte: action started in Super Saiyan
!cb_act_imp    = !CB+$1C   ; byte: punch impact frame
!cb_act_fl     = !CB+$1D   ; byte: !AF_* flags
!cb_act_pause  = !CB+$1E   ; byte: contact hold frames (hitPause)
!cb_queued     = !CB+$1F   ; byte: buffered punch
!cb_combo      = !CB+$20   ; byte
!cb_blast_cd   = !CB+$21   ; byte: ki cooldown
!cb_combo_until = !CB+$22  ; word
!cb_held       = !CB+$24   ; word: attackHeld
!cb_charge     = !CB+$26   ; word: Kamehameha charge frames
!cb_charging   = !CB+$28   ; byte
!cb_ki_hand    = !CB+$29   ; byte: next palm
!cb_blocked    = !CB+$2A   ; byte: attackBlocked
!cb_ki_blk     = !CB+$2B   ; byte: kiBlocked
!cb_pow_blk    = !CB+$2C   ; byte: powerBlocked
!cb_tap        = !CB+$2D   ; byte: native B pulse frames left
!cb_power      = !CB+$2E   ; word: focus aura 0-96 (powerCharge)
!cb_panel      = !CB+$30   ; word: X routed to native Y ($4000) or Start ($1000)
!cb_mask       = !CB+$32   ; word: buttons hidden from the game this frame
!cb_inject     = !CB+$34   ; word: buttons added for the game this frame
!cb_rec_map    = !CB+$36   ; word: status recovery map ($FFFF none)
!cb_rec_until  = !CB+$38   ; word: status recovery end (cb_frame)
!cb_rec_pend   = !CB+$3A   ; byte: recovery waiting for control
!cb_rec_burst  = !CB+$3B   ; byte: shell of the pending burst
!cb_rec_status = !CB+$3C   ; word: statuses that were broken
!cb_quake      = !CB+$3E   ; byte: BG quake frames left
!cb_quake_prev = !CB+$3F   ; byte: $49 before the quake
!cb_fieldv     = !CB+$40   ; byte: field interrupt vectors installed (cached per frame)
!cb_attack_id  = !CB+$41   ; byte: destroy attack serial (beams)
!cb_hr_frame   = !CB+$42   ; word: hit recovery: core tick of the hit
!cb_hr_map     = !CB+$44   ; word
!cb_hr_tier    = !CB+$46   ; byte: 0 none, 1 ordinary, 2 boss, 3 dangerous
!cb_hr_recoil  = !CB+$47   ; byte: recoil pixels spent
!cb_def_base   = !CB+$48   ; 2 words: unboosted E1A5 / E1A8
!cb_def_wr     = !CB+$4C   ; 2 words: values written
!cb_def_valid  = !CB+$50   ; byte
!cb_react      = !CB+$51   ; byte: reaction mode (!GOKU_K_DEFLECT/RESIST), 0 none
!cb_react_tick = !CB+$52   ; word: core tick of the reaction
!cb_react_map  = !CB+$54   ; word
!cb_react_face = !CB+$56   ; byte
!cb_rebuild    = !CB+$57   ; byte: fresh level-table read seen (agility)
!cb_contacts   = !CB+$58   ; word: eligible physical contacts
!cb_deflected  = !CB+$5A   ; word: deflections (diagnostics)
!cb_parry_until = !CB+$5C  ; word: core tick before the next deflection
!cb_agi_base   = !CB+$5E   ; byte: unweighted agility
!cb_agi_wr     = !CB+$5F   ; byte: agility written
!cb_agi_valid  = !CB+$60   ; byte
!cb_world      = !CB+$61   ; byte: last dispatch was world flight
!cb_lock       = !CB+$62   ; word: API: other modules forbid attacks (bit per owner)
!cb_inlock     = !CB+$64   ; word: API: other modules own player input (bit per owner)
!cb_danger     = !CB+$66   ; word: API: a dangerous encounter is active (bit per owner)
!cb_recovered  = !CB+$68   ; word: shortened recoveries (diagnostics)
!cb_hits       = !CB+$6A   ; word: hits queued by combat (diagnostics)
!cb_kb_iter    = !CB+$6C   ; word: launch loop mask
!cb_phase      = !CB+$6E   ; byte: frame phase (staggered stat writes)
!cb_steps      = !CB+$6F   ; byte: steps left in this field frame (catch-up)
!cb_t0         = !CB+$70   ; scratch words $70-$9F (call-local)
!cb_t1         = !CB+$72
!cb_t2         = !CB+$74
!cb_t3         = !CB+$76
!cb_t4         = !CB+$78
!cb_t5         = !CB+$7A
!cb_t6         = !CB+$7C
!cb_t7         = !CB+$7E
!cb_t8         = !CB+$80
!cb_t9         = !CB+$82
!cb_ta         = !CB+$84
!cb_tb         = !CB+$86
!cb_tc         = !CB+$88
!cb_td         = !CB+$8A
!cb_te         = !CB+$8C
!cb_tf         = !CB+$8E
; attack geometry (combat_targets arguments, also read by bindings)
!ag_x          = !CB+$90   ; word: origin x (map)
!ag_y          = !CB+$92   ; word: origin y
!ag_dir        = !CB+$94   ; word: facing 0-3
!ag_range      = !CB+$96   ; word: forward range
!ag_width      = !CB+$98   ; word: half width (inclusive)
!ag_behind     = !CB+$9A   ; word
!ag_cy         = !CB+$9C   ; word: centre y offset
!ag_list       = !CB+$9E   ; word: bit mask of matching slots 3-11 (bit = slot-3)
; beam (one at a time)
!bm_charge     = !CB+$A0   ; byte: charge of the live beam
!bm_mega       = !CB+$A1   ; byte
!bm_range      = !CB+$A2   ; word
!bm_speed      = !CB+$A4   ; word
!bm_id         = !CB+$A6   ; byte: destroy attack id of the beam
!bm_barrier    = !CB+$A7   ; byte: a barrier/switch reacted (once per beam)
; transform burst
!cb_burst_done = !CB+$A8   ; byte (diagnostics: hits of the last burst)
!cb_form_pub   = !CB+$A9   ; byte: form last written to !goku_form ($FF none)
!cb_hit_dmg    = !CB+$AA   ; word: combat_hit argument: damage
!cb_hit_dir    = !CB+$AC   ; word: direction 0-3, or $8000 radial (cb_hit_dx/dy)
!cb_hit_dx     = !CB+$AE   ; word: radial: launch x offset at full distance (8.8)
!cb_hit_dy     = !CB+$B0   ; word
!cb_hit_launch = !CB+$B2   ; byte: launch small enemies
!cb_hit_before = !CB+$B4   ; word: result: HP before
!cb_hit_after  = !CB+$B6   ; word: result: HP after (0 floor)
!cb_hit_orb    = !CB+$B8   ; byte: result: a puzzle orb took the hit
!cb_def_form   = !CB+$B9   ; byte: form of the last defense write
!cb_fx_vram    = !CB+$BA   ; word: placeholder VRAM state
!cb_fx_round   = !CB+$BC   ; byte: placeholder refresh cadence
!cb_ext_kind   = !CB+$BD   ; byte: action kind seen in !goku_act that combat did not set
!cb_fx_mask    = !CB+$BE   ; word: live effect records (bit = record)
!cb_fx_iter    = !CB+$C0   ; word: effect loop mask
!cb_kb_mask    = !CB+$C2   ; word: live launches (bit = enemy slot - 3)
!cb_vblanks    = !CB+$C4   ; word: field vblanks (NMI hook C0:C0BA), the browser's 60 Hz clock
!cb_vb_last    = !CB+$C6   ; word: cb_vblanks at the last field frame
!cb_scale      = !CB+$C8   ; word: damageScale() of this frame
!cb_gi         = !CB+$CA   ; byte: Heavy Gi worn
!cb_active     = !CB+$CB   ; byte: Goku active (cached for the frame)
!cb_basemask   = !CB+$CC   ; word: native mask from this field frame's gate (all steps)
!cb_menuflag   = !CB+$CE   ; byte: a native menu owns the input this field frame
!cb_up_act     = !CB+$CF   ; byte: cb_active at the last stats upkeep pass
!cb_sa_wr      = !CB+$D0   ; word: E188 / E189 (strength, agility) after the last stats upkeep
!cb_pub_kind   = !CB+$D2   ; byte: action kind combat last wrote to !goku_act (0 none)
!cb_quiet      = !CB+$D3   ; word: combat's own state is idle (set by a full logic frame,
                           ; cleared by anything else that may change it: APIs, hooks, menus)
!cb_gi_seen    = !CB+$D5   ; byte: body armor ($E1E1) at the last stats upkeep pass
!cb_d2         = !CB+$D6   ; word: burst: squared distance of the target
!cb_mq         = !CB+$D8   ; 4 words: math scratch ($D8-$DF)
!cb_mq1        = !CB+$DA
!cb_mq2        = !CB+$DC
!cb_mq3        = !CB+$DE
!cb_recovering = !CB+$E0   ; word: a status recovery owns this frame's input
!cb_raw        = !CB+$E2   ; word: physical pad of this step (catch-up: the last step gets the new read)
!cb_m0         = !CB+$E4   ; math scratch words $E4-$F7 (cb_isqrt32, cb_div32)
!cb_m1         = !CB+$E6
!cb_m2         = !CB+$E8
!cb_m3         = !CB+$EA
!cb_m4         = !CB+$EC
!cb_m5         = !CB+$EE
!cb_m6         = !CB+$F0
!cb_m7         = !CB+$F2
!cb_m8         = !CB+$F4
!cb_m9         = !CB+$F6
!cb_bx         = !CB+$F8   ; word: burst: target x - Goku x
!cb_by         = !CB+$FA   ; word: burst: target y - Goku y
!cb_bslot      = !CB+$FC   ; word: burst: actor offset in the loop
!cb_inj_all    = !CB+$FE   ; word: buttons injected by any step of this field frame
!CB_END        = !CB+$100

; action flags (cb_act_fl)
!AF_HIT    = $01   ; punch struck
!AF_BURST  = $02   ; transformation burst fired
!AF_FULL   = $04   ; charge reached full power
!AF_REVEAL = $08   ; first transformation (long reveal)
!AF_SHOT   = $10   ; ki fired

; ---------------------------------------------------------------------------
; SRAM work tables (!SRAM_WORK_COMBAT, $400 bytes, long addressing).
!CW = !SRAM_WORK_COMBAT
!ER       = !CW+$000       ; 16 effect records x 16 bytes
!ER_N     = 16
!ER_SIZE  = 16
!KB       = !CW+$100       ; 9 launches x 16 bytes (enemy slots 3-11)
!SM       = !CW+$190       ; 9 sound marks x 8 bytes
!cb_warm  = !CW+$1D8       ; 6 bytes: fx's !fx_evict when the contact cells of blow + 3 * Super Saiyan
                           ; were last found resident (cb_fx_prep)
                           ; $1DE-$1EF free (the beam pulses moved to !BP below)
!PADH     = !CW+$1F0       ; pad 1 at each of the last 4 field vblanks (NMI tail)
; destroy_hit arguments (attack against the map; bind.asm), long addressing
!da_len   = !CW+$1F8       ; word: reach in pixels
!da_half  = !CW+$1FA       ; word: half width
!da_taper = !CW+$1FC       ; word: taper length (full wave 44) or 0
!da_str   = !CW+$1FE       ; word: strength 0-256
!da_id    = !CW+$200       ; word: attack id (beams), 0 one-shot
; the live beam's picture for this field frame, drawn at the frame end
; (fx keeps continuous draws only from the frame callbacks)
!bd_on    = !CW+$202       ; word: nonzero = draw
!bd_kind  = !CW+$204       ; word: fx_beam A (kind | flags << 8)
!bd_x     = !CW+$206       ; word: palms (map)
!bd_y     = !CW+$208
!bd_dir   = !CW+$20A       ; word: facing 0-3
!bd_len   = !CW+$20C       ; word: length
!bd_half  = !CW+$20E       ; word: half width
!bd_taper = !CW+$210       ; word: taper (full wave 44) or 0
!bd_age   = !CW+$212       ; word: beam age
; beam pulse timers per target bit (bits 0-8 = actor slots 3-11, 9-15 =
; virtual targets): byte species, byte beam age of the last pulse
!BP       = !CW+$214       ; 16 x 2 bytes
; Virtual targets (virtual.asm; registered in modules.asm
; modules_combat_targets): the step's cache of every entry's query.
!VT       = !CW+$234
!vt_state = !VT+$00        ; word: $8000 | live entries (bit i = entry i = target bit 9+i)
                           ; once filled this field frame, 0 = stale (frame start, hits)
!vt_spare = !VT+$02        ; word (free)
!vt_hits  = !VT+$04        ; word: virtual hits (diagnostics; the log index)
!VT_E     = !VT+$06        ; 7 entries x 8 bytes: +0 species | terrain << 8, +2 x, +4 y, +6 spare
!VT_N     = 7
!VT_LOG   = !VT_E+$38      ; (7 x 8) the last 8 virtual hits x 8 bytes (tests): +0 cb_frame,
                           ; +2 damage, +4 entry | melee << 8, +6 HP taken
!VT_END   = !VT_LOG+$40    ; (8 x 8)
; (asar evaluates left to right: these offsets are written out, not multiplied)
; combat_api_beam's record (beamGeometry of the live beam, long addressing)
!cb_beam       = !VT_END
!cb_beam_x     = !cb_beam+$00   ; word: palms (map)
!cb_beam_y     = !cb_beam+$02
!cb_beam_dx    = !cb_beam+$04   ; word: -1 / 0 / 1
!cb_beam_dy    = !cb_beam+$06
!cb_beam_len   = !cb_beam+$08   ; word: length (px)
!cb_beam_half  = !cb_beam+$0A   ; word: half width (8.8)
!cb_beam_super = !cb_beam+$0C   ; byte: 1 fired as Super Saiyan
!cb_beam_mega  = !cb_beam+$0D   ; byte: 1 full Super Saiyan wave
!cb_beam_age   = !cb_beam+$0E   ; word: max - life
!cb_beam_life  = !cb_beam+$10   ; word
!cb_beam_taper = !cb_beam+$12   ; word: 44 for the full wave, else 0
!cb_inhold     = !cb_beam+$14   ; word: owner bits of !cb_inlock that keep effects running
!cb_vq         = !cb_beam+$16   ; word: combat_api_vtarget: terrain | entry flags << 8 (+2: its scratch)
!CW_END   = !cb_beam+$1A
assert !CW_END <= !CW+$400, "combat SRAM work area overflow"
assert !vt_hits == $317E38, "snes/test/combat/lib.lua reads !vt_hits at $31:7E38"
assert !VT_LOG == $317E72, "snes/test/combat/lib.lua reads !VT_LOG at $31:7E72"
; Test builds (-DCOMBAT_TEST, snes/test/combat): a mailbox the logic reads at
; the start of each field frame, a receive hook (modules.asm) and the beam
; API's answer at each frame end.
!CBT          = !CW+$300
!cbt_cmd      = !CBT+$00   ; word: 1 input hold, 2 input lock, 3 unlock (owner !cbt_owner), 4 target-box query (result in owner); 0 when done
!cbt_owner    = !CBT+$02   ; word
!cbt_rx_mode  = !CBT+$04   ; word: test receive hook: 0 keep, 1 cap at !cbt_rx_cap, 2 none
!cbt_rx_cap   = !CBT+$06   ; word
!cbt_rx_in    = !CBT+$08   ; word: the damage the hook saw last
!cbt_rx_n     = !CBT+$0A   ; word: its calls
!cbt_beam_c   = !CBT+$0C   ; word: combat_api_beam at the frame end: 1 live, 0 none
!cbt_beam_a   = !CBT+$0E   ; word: its A (facing | flags)
!cbt_beam     = !CBT+$10   ; $14 bytes: its !cb_beam record
assert !CBT == $317F00, "snes/test/combat/lib.lua reads the test block at $31:7F00"
; effect record fields
!er_kind  = $00   ; byte: !ERK_*
!er_flags = $01   ; byte: !ERF_*
!er_x     = $02   ; word: map x
!er_y     = $04   ; word: map y
!er_dir   = $06   ; byte: facing 0-3
!er_hold  = $07   ; byte
!er_life  = $08   ; byte
!er_max   = $09   ; byte
!er_dmg   = $0A   ; word
!er_hits  = $0C   ; word: slot bit mask
!er_aux   = $0E   ; word: ki half width / burst radius / beam charge; an impact's impact frame
!ERK_IMPACT = 1
!ERK_KI     = 3
!ERK_BEAM   = 4
!ERK_BURST  = 5
!ERK_STATUS = 6
; An impact's impact frame (er_aux, fx FX_HIT C): starburst size + 1 in
; bits 0-2 (1 ki, 2 jab, 3 cross, 4 kick), the kick's shockwave, the struck
; actor's slot (3-11) drawn white in bits 4-7.
!CB_IMP_SHOCK = $0008
!CB_IMP_SLOT  = $0010   ; actor slot multiplier
!ERF_SUPER  = $01
!ERF_MEGA   = $02
!ERF_HAND   = $04
!ERF_FIRE   = $10   ; status burst shells
!ERF_ICE    = $20
!ERF_BALLOON = $40
; launch record fields
!kb_on    = $00   ; byte: 1 active
!kb_sp    = $01   ; byte: species at the hit
!kb_x     = $02   ; word: start x
!kb_y     = $04   ; word: start y
!kb_dir   = $06   ; byte: 0-3, or $80 radial
!kb_hold  = $07   ; byte
!kb_age   = $08   ; byte
!kb_dist  = $09   ; byte: 56 / 88
!kb_dx    = $0A   ; word: radial: x offset at full distance (8.8 signed)
!kb_dy    = $0C   ; word
; sound mark fields
!sm_on    = $00   ; byte
!sm_sp    = $01   ; byte
!sm_frame = $02   ; word: cb_frame of the hit
!sm_map   = $04   ; word

; Persistent (SRAM, saved with the GAME FILE sidecar)
!pc_flags = !PERSIST_COMBAT+$00   ; byte: !PCF_*
!PCF_REVEALED = $01               ; the first Super Saiyan reveal was shown

; Pad bits ($4218 layout) used by combat
!IN_B  = $8000
!IN_Y  = $4000     ; ki
!IN_SEL = $2000
!IN_ST = $1000
!IN_UP = $0800
!IN_DN = $0400
!IN_LT = $0200
!IN_RT = $0100
!IN_A  = $0080
!IN_X  = $0040     ; ring / back
!IN_L  = $0020
!IN_R  = $0010
!IN_DIRS = $0F00

; Story hooks / queries implemented by combat (story/hooks.asm). Story's
; test builds (-DSTORY_TEST) answer every foreign hook and query from their
; own tables (story/testhooks.asm, included before this file): keep those.
if not(defined("STORY_TEST"))
	!STORY_HOOK_EQUIP_CONFISCATE = combat_equip_confiscate
	!STORY_QUERY_EQUIP_WEIGHTED = combat_q_weighted
endif

; Debug scene select: combat answers its preset hook kinds (api.asm) for
; every preset unless another module owns the ANY slot (debug's test builds
; log every hook themselves).
if defined("DEBUG_HOOK_FORM")
	if not(defined("DEBUG_PRESET_HOOK_ANY"))
		!DEBUG_PRESET_HOOK_ANY = combat_debug_hook
	endif
endif

; Audio cue ids (snes/gen/audio.mjs SHOTS order; bind.asm asserts them
; against the audio module when it is present).
!AUDIO_SFX_SWING_ID       = 1
!AUDIO_SFX_KICK_SWING_ID  = 2
!AUDIO_SFX_HIT_ID         = 3
!AUDIO_SFX_KICK_ID        = 4
!AUDIO_SFX_BLAST_ID       = 5
!AUDIO_SFX_IMPACT_ID      = 6
!AUDIO_SFX_BEAM_ID        = 8
!AUDIO_SFX_CHARGED_ID     = 9
!AUDIO_SFX_TRANSFORM_ID   = 10
!AUDIO_SFX_REVERT_ID      = 11
!AUDIO_SFX_POWER_BURST_ID = 12
!AUDIO_SFX_DEFLECT_ID     = 13
!AUDIO_SFX_BALLOON_POP_ID = 14
!AUDIO_SFX_ICE_BREAK_ID   = 15
!AUDIO_SFX_CHARGE_ID      = 0     ; the charge is a loop (bind.asm), not a shot

; combat placeholder sprites while no fx module draws: off once the real fx
; library is in the build (it owns the OBJ regions and the effect cells; its
; request block's !fx_busy marks it, the API-only stub has none)
if not(defined("COMBAT_FX_PLACEHOLDER"))
	if defined("fx_busy")
		!COMBAT_FX_PLACEHOLDER = 0
	else
		!COMBAT_FX_PLACEHOLDER = 1
	endif
endif
!COMBAT_OWNER = $02                 ; core_vram_claim owner id

; Virtual targets (virtual.asm), registered in modules.asm
; modules_combat_targets: `dl <query>, <hit> : db <browser entity index>,
; <flags>` per target; at most 7 (target bits 9-15).
!VT_TABLE = modules_combat_targets
!VT_TABLE_LEN = modules_combat_targets_end-modules_combat_targets
!VT_BIT0 = 9                        ; target bit of entry 0 (bits 0-8: actor slots 3-11)
!CVT_AIRBORNE = $01                 ; flag: hovers (Instant Transmission may end in the air)
; Goku's live beam geometry for other modules (api.asm combat_api_beam).
!COMBAT_API_BEAM = combat_api_beam

pushpc
org !DATA_COMBAT
combat_data_start:
incsrc "combat/data.asm"
combat_fxstub_tiles:
incbin "combat/fxstub.bin"
combat_data_end:
assert combat_data_end <= !DATA_COMBAT+$8000, "combat data bank overflow"
pullpc

pushpc
org !CODE_COMBAT
combat_code_start:
incsrc "frame.asm"
incsrc "action.asm"
if defined("WORLD_MAGIC")
	incsrc "world.asm"
endif
incsrc "attack.asm"
incsrc "native.asm"
incsrc "stats.asm"
incsrc "effects.asm"
incsrc "virtual.asm"
incsrc "api.asm"
combat_code_end:
assert combat_code_end <= !CODE_COMBAT+$7000, "combat code overflows into the binding area ($A2:F000)"
pullpc

incsrc "hooks.asm"
